'use strict';
const pageView=document.body.dataset?.page==='library'?'library':'discover';
// The host can serve the root HTML as a static asset before the root route runs.
function legacyCollectionPath(){const url=new URL(location.href);if(pageView!=='discover'||url.searchParams.get('tab')!=='library')return null;url.searchParams.delete('tab');return '/koleksiyonum'+url.search+url.hash;}
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).toLocaleLowerCase('tr').replace(/ı/g,'i').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const moodDefs=[['','compass','Hepsine açığım'],['relax','leaf','Kafamı dağıtayım'],['world','globe','Bir dünyada kaybolayım'],['challenge','flame','Biraz zorlanayım'],['story','book','Hikâyeye dalayım'],['think','puzzle','Kafamı çalıştırayım']];
const statusDefs=[['','Hepsi'],['planned','Oynayacağım'],['playing','Oynuyorum'],['completed','Bitirdim'],['paused','Ara verdim']];
const curationDefs=[{id:'',icon:'compass',name:'Hepsine açığım',desc:'Bir yön seçmeden bütün dünyalara göz at.'},{id:'world',icon:'globe',name:'Bir dünyada kaybolayım',desc:'Keşif, açık dünyalar ve kendi yolunu çizme.',mood:'world'},{id:'relax',icon:'leaf',name:'Kafamı dağıtayım',desc:'Koşturmayı bırakıp daha sakin bir ritim bul.',mood:'relax'},{id:'story',icon:'book',name:'Hikâyeye dalayım',desc:'Karakterler, diyaloglar ve akılda kalan yolculuklar.',mood:'story'},{id:'think',icon:'puzzle',name:'Kafamı çalıştırayım',desc:'Bulmacalar, stratejiler ve birbirine bağlı sistemler.',mood:'think'},{id:'challenge',icon:'flame',name:'Biraz zorlanayım',desc:'Denemeyi, öğrenmeyi ve yeniden başlamayı sevenlere.',mood:'challenge'}];
const state={games:[],total:0,pageCount:1,catalogStats:{games:0,covers:0,scores:0},moodCounts:{},loading:false,user:null,signin:'/signin-with-chatgpt?return_to=%2F',signout:'/signout-with-chatgpt?return_to=%2F',entries:new Map(),lists:[],views:{},mood:'',tab:pageView,status:'',collection:'',curation:'',page:1,compare:new Set(),current:null,pending:new Set(),loaded:false,fetchedAt:null,editingCollection:null};
let toastTimer,searchTimer,sourceInfo=null,legacy=[];
// Only ten result pages and the small set used by detail/compare/spotlight are retained.
const gameCache=new Map(),pageCache=new Map(),pageCacheLimit=10,gameCacheLimit=360;
const validGameId=id=>typeof id==='string'&&/^[a-z0-9][a-z0-9-]{0,99}$/.test(id);
let catalogSequence=0,catalogController=null,detailSequence=0;
function trimGameCache(){
 const pinned=new Set([...state.games.map(g=>g.id),...state.compare,state.current?.id,...spotlightGames.map(g=>g.gameId)]);
 for(const page of pageCache.values())for(const game of page.games)pinned.add(game.id);
 if(state.current)for(const item of relatedRecommendations(state.current))pinned.add(item.game.id);
 for(const id of gameCache.keys()){if(gameCache.size<=gameCacheLimit)break;if(!pinned.has(id)){gameCache.delete(id);delete state.views[id];}}
}
function rememberGames(games){for(const g of games){if(!g||typeof g.id!=='string')continue;gameCache.delete(g.id);gameCache.set(g.id,g);if(Number.isFinite(g.viewCount))state.views[g.id]=Math.max(state.views[g.id]||0,g.viewCount);}trimGameCache();return games;}
// Boş sınır filtresizdir; sıfır geçerli bir sınırdır.
const scoreRanges=[
 {min:'rating',max:'ratingMax',label:'Metacritic kullanıcı puanı',short:'Metacritic',limit:10,unit:'/10'},
 {min:'steamMin',max:'steamMax',label:'Steam olumlu değerlendirme oranı',short:'Steam',limit:100,unit:'%'},
 {min:'mcCountMin',max:'mcCountMax',label:'Metacritic değerlendirme sayısı',short:'Metacritic değerlendirme',limit:Number.MAX_SAFE_INTEGER,count:true},
 {min:'steamCountMin',max:'steamCountMax',label:'Steam değerlendirme sayısı',short:'Steam değerlendirme',limit:Number.MAX_SAFE_INTEGER,count:true}
];
function rangeValues(){const values={};for(const r of scoreRanges)for(const key of [r.min,r.max])$(key).removeAttribute('aria-invalid');for(const r of scoreRanges){for(const key of [r.min,r.max]){const raw=$(key).value.trim();$(key).removeAttribute('aria-invalid');if(!raw)continue;if(!(r.count?/^\d+$/:/^\d+(?:[.,]\d+)?$/).test(raw)){ $(key).setAttribute('aria-invalid','true');throw new Error(r.label+': geçerli '+(r.count?'bir tam sayı':'bir sayı')+' gir.');}const value=Number(raw.replace(',','.'));if(!Number.isFinite(value)||value<0||value>r.limit||(r.count&&!Number.isSafeInteger(value))){$(key).setAttribute('aria-invalid','true');throw new Error(r.label+': '+(r.count?'sıfır veya pozitif bir tam sayı':'0–'+r.limit+' arasında bir sayı')+' gir.');}values[key]=String(value);}if(values[r.min]!==undefined&&values[r.max]!==undefined&&Number(values[r.min])>Number(values[r.max])){for(const key of [r.min,r.max])$(key).setAttribute('aria-invalid','true');throw new Error(r.label+': en az değeri en fazla değerinden büyük olamaz.');}}return values;}
function checkRanges(){try{rangeValues();$('scoreFilterError').hidden=true;return true;}catch(e){$('scoreFilterError').textContent=e.message+' Sonuçlar değiştirilmedi.';$('scoreFilterError').hidden=false;return false;}}
function clearRanges(){for(const r of scoreRanges)for(const key of [r.min,r.max]){$(key).value='';$(key).removeAttribute('aria-invalid');}$('scoreFilterError').hidden=true;}
function rangeChips(){return scoreRanges.map(r=>{const lo=$(r.min).value.trim(),hi=$(r.max).value.trim();if(!lo&&!hi)return '';const fmt=v=>r.count?Number(v).toLocaleString('tr'):v.replace('.',',');const bounds=lo&&hi?fmt(lo)+'–'+fmt(hi):lo?'en az '+fmt(lo):'en fazla '+fmt(hi);const text=r.short+' '+bounds+(r.unit?' '+r.unit:'');return `<button type="button" class="filter-chip" data-clear-range="${r.min},${r.max}" aria-label="${esc(text)} filtresini kaldır">${esc(text)} <span aria-hidden="true">×</span></button>`;}).join('');}
function renderFilterSummary(){if(!checkRanges())return;const text=[state.mood?moodDefs.find(m=>m[0]===state.mood)[2]:'',$('genre').value,$('era').selectedIndex?$('era').selectedOptions[0].textContent:'',$('system').value,$('features').value==='turkish'?'Türkçe arayüz':$('features').value==='coop'?'Co-op':'',$('search').value?'Arama: '+$('search').value:''].filter(Boolean).join(' · ');$('activeFilters').innerHTML=(text?'<span>'+esc(text)+'</span>':'')+rangeChips();}
function catalogQuery({random=false}={}){const p=new URLSearchParams({page:String(state.page),pageSize:random?'1':'24'});for(const [key,value]of Object.entries({q:$('search').value.trim(),genre:$('genre').value,era:$('era').value,mood:state.mood,...rangeValues(),system:$('system').value,features:$('features').value,sort:$('sort').value,status:state.user?state.status:'',collection:state.user?state.collection:'',library:state.tab==='library'&&state.user?'1':''}))if(value)p.set(key,value);if(random)p.set('random','1');return p;}
function catalogMetadata(c){state.total=c.total;state.page=c.page;state.pageCount=Math.max(1,c.pageCount);state.catalogStats=c.catalogStats;state.moodCounts=c.moodCounts||{};state.tagLabels=c.steamTagLabels||{};state.fetchedAt=c.fetchedAt;sourceInfo=c;const genre=$('genre').value;$('genre').innerHTML='<option value="">Tüm türler</option>'+(c.genres||[]).map(t=>`<option>${esc(t)}</option>`).join('');$('genre').value=genre;}
async function loadPage({force=false,timeoutMs=20000}={}){
 const sequence=++catalogSequence;catalogController?.abort();if(!checkRanges()){state.loading=false;$('grid').setAttribute('aria-busy','false');$('resultCount').textContent=state.loaded?state.total+' oyun · Son geçerli sonuçlar':'Filtre aralığını düzelt';return false;}const controller=catalogController=new AbortController();let timedOut=false;
 const timeout=setTimeout(()=>{timedOut=true;controller.abort();},timeoutMs);
 const path='/api/catalog?'+catalogQuery(),storedPage=pageCache.get(path),cached=!force&&storedPage&&Date.now()-storedPage.cachedAt<30000?storedPage:null;state.loading=true;$('grid').setAttribute('aria-busy','true');$('resultCount').textContent='Oyunlar yükleniyor…';
 try{const incoming=cached||await api(path,'GET',undefined,{signal:controller.signal}),c=state.tab==='library'&&!state.user?{...incoming,games:[],total:0,page:1,pageCount:1}:incoming;if(sequence!==catalogSequence)return false;if(c.apiVersion!==2||!Array.isArray(c.games)||c.games.length>24||!Number.isInteger(c.total)||!Number.isInteger(c.page)||!Number.isInteger(c.pageCount)||!c.catalogStats)throw new Error('Katalog yanıtı okunamadı. Yeniden dene.');pageCache.delete(path);pageCache.set(path,{...c,cachedAt:cached?cached.cachedAt:Date.now()});while(pageCache.size>pageCacheLimit)pageCache.delete(pageCache.keys().next().value);state.games=c.games;catalogMetadata(c);rememberGames(c.games);state.loaded=true;state.loading=false;render();$('sourceDate').textContent=c.fetchedAt?'Son güncelleme: '+new Date(c.fetchedAt).toLocaleString('tr'):'Katalog kullanıma hazır';return true;}
 catch(e){if(sequence!==catalogSequence||(!timedOut&&e.name==='AbortError'))return false;state.loading=false;$('grid').innerHTML=`<div class="empty"><h3>Katalog şu an yüklenemedi.</h3><p>${esc(timedOut?'Arama yanıtı gecikti. Yeniden dene.':e.message)}</p><button id="retryCatalog">Yeniden dene</button></div>`;$('resultCount').textContent='Bağlantı bekleniyor';return false;}
 finally{clearTimeout(timeout);if(sequence===catalogSequence)$('grid').setAttribute('aria-busy','false');}
}
function submitSearch(){clearTimeout(searchTimer);if(!checkRanges()){catalogSequence++;catalogController?.abort();state.loading=false;$('grid').setAttribute('aria-busy','false');$('resultCount').textContent=state.loaded?state.total+' oyun · Son geçerli sonuçlar':'Filtre aralığını düzelt';return false;}state.page=1;return loadPage();}
async function hydrateGames(ids){const unique=[...new Set(ids)].filter(validGameId),missing=unique.filter(id=>!nameGame(id)),resolved=unique.map(nameGame).filter(Boolean);for(let start=0;start<missing.length;start+=60){const r=await api('/api/games?ids='+encodeURIComponent(missing.slice(start,start+60).join(',')));if(!Array.isArray(r.games)||r.games.length>60)throw new Error('Oyun kayıtları okunamadı.');resolved.push(...r.games);rememberGames(r.games);}return resolved;}
async function openGame(id){const sequence=++detailSequence;try{const [g]=await hydrateGames([id]);if(sequence!==detailSequence)return;if(g)detail(g);else toast('Bu oyun katalogda bulunamadı.');}catch(e){if(sequence===detailSequence)toast(e.message);}}
async function libraryChanged(){pageCache.clear();if(state.tab==='library')await loadPage({force:true});else render();}

function cover(g,hero=false){const src=g.coverUrl;let valid=false;try{const u=new URL(src);valid=u.protocol==='https:'&&(u.hostname.endsWith('.steamstatic.com')||u.hostname==='steamstatic.com');}catch{}if(!valid)return `<div class="cover-unavailable"><span>${esc(g.name)}</span><small>Kapak görseli bulunamadı</small></div>`;return `<img class="game-photo" src="${esc(src)}" alt="${esc(g.name)} oyun kapağı" loading="${hero?'eager':'lazy'}" decoding="async" ${hero?'fetchpriority="high"':''} width="460" height="215" data-fallback="${esc(g.coverFallbackUrl||'')}" data-game-name="${esc(g.name)}">`; }
function userScore(g){const r=g.metacriticUser;return g.platforms?.includes('PC')&&r&&r.metric==='user-score'&&Number.isFinite(r.score)&&r.score>=0&&r.score<=10?r:null;}
function scoreText(g){const r=userScore(g);return r?r.score.toLocaleString('tr',{minimumFractionDigits:1,maximumFractionDigits:1})+'/10':'Veri yok';}
function scoreAge(r){const p=r.provenance;if(p?.method==='public-historical-dataset')return 'Kaynak veri tarihi: '+p.datasetCollectedAt;if(p?.method!=='public-primary-cache')return '';const label=p.sourceCrawlLabel;const months=/^(\d+) months ago$/.exec(label||'');return label==='last month'?'Kaynak sayfa geçen ay taranmış':months?'Kaynak sayfa '+months[1]+' ay önce taranmış':'Önbellekteki kaynak sayfa: '+label;}
function scoreRecordText(g){const r=userScore(g);return r?[(r.scoreDate?'Puan tarihi: '+r.scoreDate:'Puan ölçüm tarihi belirtilmemiş'),'Kayıt tarihi: '+r.snapshotDate,r.platform||'Platform belirtilmemiş',scoreAge(r),r.provenance?.conflictingCachedObservation?'Kaynak önbellekleri farklı; güncellik belirsiz':''].filter(Boolean).join(' · '):'Veri yok';}
function steamScore(g){const r=g.steamReview;return r&&Number.isFinite(r.positivePercent)&&r.positivePercent>=0&&r.positivePercent<=100?r:null;}
function scoreCount(n){return Number.isSafeInteger(n)&&n>=0?n.toLocaleString('tr')+' değerlendirme':'Değerlendirme sayısı bilinmiyor';}
function scoreBrand(source){return source==='metacritic'?'<svg class="score-brand-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="#f4ce28"/><circle cx="12" cy="12" r="8.5" fill="#252925"/><text x="12" y="16.5" text-anchor="middle" fill="#fff" font-family="Arial,sans-serif" font-size="17" font-weight="700" font-style="italic" transform="rotate(-18 12 12)">m</text></svg><span>metacritic</span>':'<svg class="score-brand-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="currentColor"/><g fill="none" stroke="var(--paper)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="16" cy="8" r="4"/><circle cx="16" cy="8" r="2.3"/><circle cx="8" cy="16" r="3"/><path d="m10 14 3.5-3.3M10.6 17.3l6.5-5.4M1.5 12.5l6.1 2.1a1.8 1.8 0 1 1-1.2 3.4l-4.2-1.5"/></g></svg><span>Steam</span>';}
function sourceScore(g,source,detail=false){
 const mc=source==='metacritic',r=mc?userScore(g):steamScore(g),name=mc?'Metacritic kullanıcı puanı':'Steam olumlu değerlendirmeleri';
 const href=mc?r?.url:Number.isSafeInteger(g.steamAppId)&&g.steamAppId>0?'https://store.steampowered.com/app/'+g.steamAppId+'/#app_reviews_hash':null;
 const brand=scoreBrand(source),heading=href?`<a class="score-brand" href="${esc(href)}" target="_blank" rel="noopener noreferrer" aria-label="${name} kaynağını aç">${brand}</a>`:`<span class="score-brand">${brand}</span>`;
 const level=r?((mc?r.score:r.positivePercent/10)>=7?'good':(mc?r.score:r.positivePercent/10)>=5?'mixed':'low'):'missing';
 const value=r?(mc?r.score.toLocaleString('tr',{minimumFractionDigits:1,maximumFractionDigits:1})+'<small>/10</small>':r.positivePercent.toLocaleString('tr')+'%'):'—';
 const count=r?scoreCount(mc?r.userRatings:r.total):'Değerlendirme sayısı bilinmiyor';
 const scope=r&&!mc?(/English/i.test(r.scope||'')?'İngilizce yorumlar':/all.languages|all languages/i.test(r.scope||'')?'Tüm diller':'Yorum dili belirtilmemiş'):'';
 const context=r?(mc?(r.platform||'Platform belirtilmemiş')+' · Tarihli kayıt':scope):'Puan kaydı yok';
 const notes=detail?(mc?(r?scoreRecordText(g)+' · Bu kayıt canlı puan değildir.':'Bu oyun için doğrulanmış kullanıcı puanı henüz eklenmemiş.'):(r?(r.retrievedAt?'Kayıt tarihi: '+r.retrievedAt+' · ':'')+'Tarihli mağaza kaydı; canlı puan değildir.':'Bu oyun için Steam değerlendirme kaydı bulunmuyor.')):'';
 return `<section class="source-score" aria-label="${name}">${heading}<div class="score-value"><strong class="score ${level}" title="${esc(mc?'Metacritic kullanıcı puanı · tarihli kaynak kaydı':'Steam olumlu değerlendirme yüzdesi · tarihli kaynak kaydı')}">${value}</strong>${!mc&&r?'<small class="score-positive">olumlu</small>':''}</div><span class="score-count">${esc(count)}</span><small class="score-context">${esc(context)}</small>${detail?'<p class="score-source-note">'+esc(notes)+'</p>':''}</section>`;
}
function scoreBadge(g,detail=false){return `<div class="score-pair${detail?' score-pair-detail':''}">${sourceScore(g,'metacritic',detail)}${sourceScore(g,'steam',detail)}</div>`;}

try{if(localStorage.getItem('neoynasam-theme')==='dark')document.body.classList.add('dark');const comparison=JSON.parse(localStorage.getItem('neoynasam-compare')||'[]');state.compare=new Set((Array.isArray(comparison)?comparison:[]).filter(validGameId).slice(0,3));const previous=JSON.parse(localStorage.getItem('neoynasam-list')||'[]');legacy=(Array.isArray(previous)?previous:[]).filter(validGameId).slice(0,2000);}catch{}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function showNotice(msg,error=false){$('notice').textContent=msg;$('notice').className='notice'+(error?' error':'');$('notice').hidden=false;}
async function api(path,method='GET',body,options={}){const deadline=Date.now()+150000;for(let attempt=0;attempt<120;attempt++){const r=await fetch(path,{...options,method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json();}catch{throw new Error('Sunucuya ulaşılamadı. Tekrar dene.');}if(r.status===202&&d.ready===false){if(attempt===119||Date.now()>=deadline)throw new Error(d.error||'Katalog hazırlanıyor. Biraz sonra yeniden dene.');if(!state.loaded)$('resultCount').textContent='Oyunlar hazırlanıyor…';await new Promise((resolve,reject)=>{const signal=options.signal;let timer;const cancel=()=>{clearTimeout(timer);signal?.removeEventListener('abort',cancel);const e=new Error('İstek iptal edildi.');e.name='AbortError';reject(e);};if(signal?.aborted){cancel();return;}signal?.addEventListener('abort',cancel,{once:true});timer=setTimeout(()=>{signal?.removeEventListener('abort',cancel);resolve();},Math.min(3000,Math.max(100,Number(d.retryAfter||1)*1000)));});continue;}if(!r.ok)throw new Error(d.error||'İşlem tamamlanamadı.');return d;}}
function nameGame(id){return gameCache.get(id);}
function syncUrl(){if(!state.loaded||!checkRanges())return;const u=new URL(location.href);for(const key of ['tab','q','genre','platform','era','mood','curation','status','collection','sort',...scoreRanges.flatMap(r=>[r.min,r.max]),'system','features','page','game'])u.searchParams.delete(key);const values={q:$('search').value,genre:$('genre').value,era:$('era').value,mood:state.mood,curation:state.curation,status:state.status,collection:state.collection,sort:$('sort').value==='editor'?'':$('sort').value,...rangeValues(),system:$('system').value,features:$('features').value,page:state.page>1?String(state.page):'',game:state.current?.id||''};for(const [k,v]of Object.entries(values))if(v)u.searchParams.set(k,v);history.replaceState(null,'',u.pathname+u.search+u.hash);}
function applyUrl(){const p=new URLSearchParams(location.search);state.page=/^\d{1,4}$/.test(p.get('page')||'')?Math.max(1,Number(p.get('page'))):1;state.tab=pageView;state.mood=moodDefs.some(m=>m[0]===p.get('mood'))?p.get('mood')||'':'';const oldCuration={worlds:'world',quiet:'relax',stories:'story',brain:'think',challenge:'challenge'};if(!state.mood&&oldCuration[p.get('curation')])state.mood=oldCuration[p.get('curation')];state.curation='';state.status=statusDefs.some(s=>s[0]===p.get('status'))?p.get('status')||'':'';state.collection=p.get('collection')||'';for(const [id,key]of [['search','q'],['genre','genre'],['era','era'],['sort','sort'],['system','system'],['features','features']]){const v=p.get(key);if(v!==null){if(id==='genre'&&v&&![...$(id).options].some(o=>o.value===v))$(id).innerHTML+=`<option value="${esc(v)}">${esc(v)}</option>`;if(id==='search'||id==='genre')$(id).value=v;else if([...$(id).options].some(o=>o.value===v))$(id).value=v;}}for(const r of scoreRanges)for(const key of [r.min,r.max])$(key).value=p.get(key)||'';}
function curationMatches(g,c){return (!c.mood||g.mood===c.mood)&&(!c.era||(g.year&&g.year<=2009));}
// Filtering and ordering are resolved by indexed server queries.
function filtered(){return state.games;}
function card(g){const e=state.entries.get(g.id),saved=!!e;return `<article class="card"><div class="cover"><button class="open-card" data-open="${esc(g.id)}" aria-label="${esc(g.name)} detaylarını aç">${cover(g)}</button><span class="number">${g.year||'KEŞİF'} / ${esc(g.genres[0]||'OYUN')}</span><button class="save ${saved?'saved':''}" data-save="${esc(g.id)}" aria-label="${esc(g.name)} ${saved?'listeden çıkar':'listeye ekle'}" aria-pressed="${saved}" ${state.pending.has(g.id)?'disabled':''}>${icon(saved?'check':'plus')}</button>${e?`<span class="status-badge">${statusDefs.find(x=>x[0]===e.status)?.[1]||'Listemde'}${e.rating?' · '+e.rating+'/5':''}</span>`:''}</div><div class="card-heading"><button data-open="${esc(g.id)}">${esc(g.name)}</button><span>${g.year||'—'}</span></div><p>${esc(g.desc)}</p><div class="tags">${g.genres.slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}<span>${g.platforms.includes('PC')?'PC':'Katalog dışı'}</span></div>${scoreBadge(g)}<div class="card-actions"><button class="compare-button ${state.compare.has(g.id)?'selected':''}" data-compare="${esc(g.id)}" aria-pressed="${state.compare.has(g.id)}">${icon(state.compare.has(g.id)?'check':'compare')} Karşılaştır</button><span class="view-count">${icon('eye')} ${Number(state.views[g.id]||0).toLocaleString('tr')} görüntüleme</span></div></article>`;}
function render(){if(!state.loaded)return;const gs=state.games,pageCount=state.pageCount,stats=state.catalogStats;if($('catalogCount'))$('catalogCount').textContent=stats.games.toLocaleString('tr');$('catalogStats').innerHTML=`<span><b>${stats.games.toLocaleString('tr')}</b> PC oyunu</span><span><b>${stats.covers.toLocaleString('tr')}</b> gerçek kapak</span><span><b>${stats.scores.toLocaleString('tr')}</b> kullanıcı puanı kaydı</span>`;$('savedCount').textContent=state.entries.size;$('listTitle').textContent=state.tab==='library'?'Kaydettiğin oyunlar.':state.mood?moodDefs.find(m=>m[0]===state.mood)[2]:'Oynayacak bir şey var.';$('sectionEyebrow').textContent=state.tab==='library'?'SANA AİT DÜNYALAR':'KEŞİF RADARI';$('resultCount').textContent=state.total+' oyun';$('discover').classList.toggle('active',state.tab==='discover');$('mylist').classList.toggle('active',state.tab==='library');$('libraryControls').hidden=state.tab!=='library'||!state.user;if($('curationGrid'))$('curationGrid').innerHTML=curationDefs.map(c=>`<button class="curation ${state.mood===c.id?'active':''}" data-curation="${c.id}" aria-pressed="${state.mood===c.id}"><span class="curation-icon">${icon(c.icon)}</span><span class="curation-arrow">${icon(state.mood===c.id?'check':'upRight')}</span><h3>${c.name}</h3><p>${c.desc}</p><small>${c.mood?(state.moodCounts[c.mood]||0):stats.games} OYUN</small></button>`).join('');if($('clearCuration'))$('clearCuration').hidden=!state.mood;$('sourceResults').innerHTML='';renderFilterSummary();$('grid').innerHTML=gs.length?gs.map(card).join(''):`<div class="empty"><h3>${state.tab==='library'&&!state.entries.size?'Koleksiyonun yeni maceraları bekliyor.':'Bu tercihlerle oyun bulamadık.'}</h3><p>${state.tab==='library'&&!state.user?'Listelerini cihazlar arasında saklamak için hesabına giriş yap.':state.tab==='library'&&!state.entries.size?'Keşfet bölümündeki + düğmesiyle ilk oyununu ekle.':'Bir tercihini değiştirerek yeniden dene.'}</p><button id="emptyReset">${state.tab==='library'&&!state.entries.size?'Oyunları keşfet':'Filtreleri temizle'}</button></div>`;$('pagination').innerHTML=pageCount>1?`<button id="prevPage" ${state.page===1?'disabled':''}>← Önceki</button><label class="page-jump">Sayfa <input id="pageJump" type="number" inputmode="numeric" aria-label="Sayfaya git" min="1" max="${pageCount}" value="${state.page}"> / ${pageCount}</label><button id="nextPage" ${state.page===pageCount?'disabled':''}>Sonraki →</button>`:'';renderLibrary();renderCompareTray();syncUrl();}
function renderLibrary(){$('statusTabs').innerHTML=statusDefs.map(([id,label])=>`<button data-status="${id}" class="${state.status===id?'active':''}">${label} <span>${[...state.entries.values()].filter(e=>!id||e.status===id).length}</span></button>`).join('');$('collectionSelect').innerHTML='<option value="">Tüm koleksiyonum</option>'+state.lists.map(l=>`<option value="${esc(l.id)}">${esc(l.name)} (${l.games.length})</option>`).join('');$('collectionSelect').value=state.collection;$('manageCollection').hidden=!state.collection;$('libraryStats').textContent=`${state.entries.size} oyun · ${state.lists.length} özel koleksiyon · ${[...state.entries.values()].filter(e=>e.status==='completed').length} tamamlanan oyun`;$('account').textContent=state.user?state.user.name.split('@')[0].split(' ')[0]:'Giriş yap';}
function clear(){state.mood='';state.curation='';state.status='';state.page=1;clearRanges();for(const id of ['search','genre','era','system','features'])$(id).value='';$('sort').value='editor';return loadPage();}
function mode(tab){if(tab!==pageView){location.assign(tab==='library'?'/koleksiyonum':'/');return false;}state.collection='';clear();$('notice').hidden=true;return true;}
async function loadLibrary(){if(!state.user)return;const [a,b]=await Promise.all([api('/api/library'),api('/api/lists')]);state.entries=new Map(a.entries.map(e=>[e.gameId,e]));state.lists=b.lists;}
async function saveGame(id,data){if(!state.user){accountDialog();return false;}if(state.pending.has(id))return false;state.pending.add(id);render();try{const old=state.entries.get(id)||{gameId:id,status:'planned',note:'',rating:null};const r=await api('/api/library','POST',{...old,...data,gameId:id});state.entries.set(id,r.entry);return true;}catch(e){toast(e.message);return false;}finally{state.pending.delete(id);await libraryChanged();}}
async function toggle(id){if(!state.user){accountDialog();return;}if(state.pending.has(id))return;if(state.entries.has(id)){const entry=state.entries.get(id);if((entry.note||entry.rating||entry.status!=='planned')&&!confirm('Bu oyunu listenden kaldırınca kişisel notu, puanı ve koleksiyon bağlantıları da silinir. Devam edilsin mi?'))return;state.pending.add(id);render();try{await api('/api/library','DELETE',{gameId:id});state.entries.delete(id);state.lists.forEach(l=>l.games=l.games.filter(x=>x!==id));toast('Oyun koleksiyonundan çıkarıldı.');}catch(e){toast(e.message);}finally{state.pending.delete(id);await libraryChanged();}}else{if(await saveGame(id,{}))toast('Oyun koleksiyonuna eklendi.');}if(state.current?.id===id)detail(state.current,false);}
function detail(g,open=true){if(!g)return;rememberGames([g]);closeMedia();stopSpotlight();state.current=g;const e=state.entries.get(g.id),storeUrl=g.platforms.includes('PC')&&Number.isSafeInteger(g.steamAppId)&&g.steamAppId>0?'https://store.steampowered.com/app/'+g.steamAppId+'/':g.url;$('detailContent').innerHTML=`${g.steamAppId?mediaMarkup(g):`<div class="detail-art">${cover(g)}</div>`}<div class="detail-body"><h2>${esc(g.name)}</h2><div class="tags">${g.genres.map(t=>`<span>${esc(t)}</span>`).join('')}</div><p class="description-kind">OYUN HAKKINDA</p><p>${esc(g.long)}</p>${scoreDetails(g)}<div class="detail-info"><div><small>YAYIN YILI</small><span>${g.year||'Belirtilmemiş'}</span></div><div><small>GELİŞTİRİCİ</small><span>${esc(g.studio||'Belirtilmemiş')}</span></div><div><small>DİĞER PLATFORMLAR · BİLGİ</small><span>${g.platforms.filter(p=>p!=='PC').map(esc).join(' · ')||'Diğer platform kaydı yok'}</span></div><div><small>PC İŞLETİM SİSTEMLERİ</small><span>${esc(g.pcSystems?.join(' · ')||'Belirtilmemiş')}</span></div><div><small>TÜRKÇE ARAYÜZ / CO-OP</small><span>${g.hasTurkish===true?'Türkçe var':g.hasTurkish===false?'Türkçe kaydı yok':'Türkçe belirtilmemiş'} · ${g.hasCoop===true?'Co-op var':g.hasCoop===false?'Co-op kaydı yok':'Co-op belirtilmemiş'}</span></div><div><small>GÖRÜNTÜLENME</small><span id="detailViews">${Number(state.views[g.id]||0).toLocaleString('tr')} · Hesap başına günde bir kez</span></div>${g.modeRaw?.length?`<div><small>OYUN MODU</small><span>${esc(g.modeRaw.join(' · '))}</span></div>`:''}</div><div class="detail-actions"><button data-save="${esc(g.id)}">${icon(e?'check':'plus')}${e?'Koleksiyonumda · Çıkar':'Koleksiyonuma ekle'}</button>${storeUrl?`<a href="${esc(storeUrl)}" target="_blank" rel="noopener noreferrer">${g.steamAppId?'Mağazada incele':'Resmî site'} </a>`:''}<button class="compare-button" data-compare="${esc(g.id)}">${icon('compare')}${state.compare.has(g.id)?'Karşılaştırmada':'Karşılaştır'}</button><button class="text-btn" id="shareGame">Bağlantıyı kopyala </button></div>${e?`<form id="entryForm" class="edit-library"><h3>Bu oyunla benim hikâyem</h3><label>Durum<select id="entryStatus">${statusDefs.filter(x=>x[0]).map(([id,label])=>`<option value="${id}" ${e.status===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Kendi puanın<select id="entryRating"><option value="">Henüz puanlamadım</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${e.rating===n?'selected':''}>${n}/5</option>`).join('')}</select></label><label>Kişisel notun<textarea id="entryNote" maxlength="1200" placeholder="Nerede kaldın, neyi sevdin?">${esc(e.note)}</textarea></label><button type="submit">Değişiklikleri kaydet</button><span class="subtle"> Notların yalnızca sana görünür.</span></form>${state.lists.length?`<div class="collection-assignment"><select id="assignCollection" aria-label="Oyun koleksiyonunu seç">${state.lists.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}${l.games.includes(g.id)?' · Eklendi':''}</option>`).join('')}</select><button id="assignAdd">Koleksiyona ekle</button><button id="assignRemove">Çıkar</button></div>`:'<p class="subtle">Koleksiyonum bölümünden özel listeler oluşturabilirsin.</p>'}`:''}${relatedMarkup()}</div>`;renderRelated(g,open);mountNativeRelated(g);if(open){if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;$('close').focus({preventScroll:true});}if(g.steamAppId)mountMedia(g);syncUrl();if(open)api('/api/views','POST',{gameId:g.id}).then(r=>{state.views[g.id]=r.count;for(const key of pageCache.keys())if(new URL(key,location.href).searchParams.get('sort')==='views')pageCache.delete(key);const node=$('detailViews');if(state.current?.id===g.id&&node)node.textContent=r.count.toLocaleString('tr')+' · Hesap başına günde bir kez';}).catch(()=>{});}
function renderCompareTray(){$('compareTray').hidden=!state.compare.size;$('compareTrayNames').textContent=[...state.compare].map(id=>nameGame(id)?.name||'Oyun yükleniyor…').join(' · ');$('compareNow').disabled=state.compare.size<2;try{localStorage.setItem('neoynasam-compare',JSON.stringify([...state.compare]));}catch{}}
function compareToggle(id){if(state.compare.has(id))state.compare.delete(id);else if(state.compare.size>=3){toast('Aynı anda en fazla 3 oyun karşılaştırabilirsin.');return;}else state.compare.add(id);render();if(state.current)detail(state.current,false);}
async function showCompare(){try{await hydrateGames([...state.compare]);}catch(e){toast(e.message);return;}const gs=[...state.compare].map(nameGame).filter(Boolean);if(gs.length<2){toast('En az iki oyun seç.');return;}const rows=[['Metacritic kullanıcı',g=>scoreText(g)],['Puan kaydı',g=>scoreRecordText(g)],['Metacritic değerlendirme sayısı',g=>scoreCount(userScore(g)?.userRatings)],['Steam olumlu yorumları',g=>steamScore(g)?steamScore(g).positivePercent+'%':'Veri yok'],['Steam değerlendirme sayısı',g=>scoreCount(steamScore(g)?.total)],['Steam yorum kapsamı',g=>steamScore(g)?(/English/i.test(steamScore(g).scope||'')?'İngilizce yorumlar':'Yorum dili belirtilmemiş'):'Veri yok'],['Türkçe arayüz kaydı',g=>g.hasTurkish===true?'Var':g.hasTurkish===false?'Kaynakta yok':'Belirtilmemiş'],['Co-op kaydı',g=>g.hasCoop===true?'Var':g.hasCoop===false?'Kaynakta yok':'Belirtilmemiş'],['PC işletim sistemleri',g=>g.pcSystems?.join(', ')||'Belirtilmemiş'],['Yayın yılı',g=>g.year||'Belirtilmemiş'],['Türler',g=>g.genres.join(', ')||'Belirtilmemiş'],['Geliştirici',g=>g.studio||'Belirtilmemiş'],['Keşif teması',g=>moodDefs.find(m=>m[0]===g.mood)?.[2]],['Benim durumum',g=>statusDefs.find(x=>x[0]===state.entries.get(g.id)?.status)?.[1]||'Listemde değil'],['Benim puanım',g=>state.entries.get(g.id)?.rating?state.entries.get(g.id).rating+'/5':'Puanlanmamış']];$('compareContent').innerHTML=`<div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>Özellik</th>${gs.map(g=>`<th><div class="mini-art">${cover(g)}</div>${esc(g.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td>${gs.map(g=>`<td>${esc(fn(g))}</td>`).join('')}</tr>`).join('')}<tr><td>İncele</td>${gs.map(g=>`<td><button data-compare-open="${esc(g.id)}">Oyuna git </button></td>`).join('')}</tr></tbody></table></div><p class="subtle">Keşif temaları editoryal sınıflandırmadır; teknik bilgiler kaynak kayıtlarından gelir. Puanlar tarihli kaynak kayıtlarıdır. Platform bilgisi bulunmayan kayıtlarda platform belirtilmemiş olarak gösterilir; bu kayıtlar doğrulanmış PC puanı olarak etiketlenmez.</p>`;$('compareDialog').showModal();}
function accountDialog(){$('accountContent').innerHTML=state.user?`<span class="eyebrow">SANA AİT BİR ALAN</span><h2>Merhaba, ${esc(state.user.name.split('@')[0])}.</h2><div class="account-box"><strong class="account-email">${esc(state.user.email)}</strong><br>${state.entries.size} oyun · ${state.lists.length} özel koleksiyon<br>Listelerin ve notların hesabına bağlı olarak veritabanında saklanır.</div><button id="accountLibrary" class="primary">Koleksiyonuma git </button><p class="subtle">Oturumunu ChatGPT hesabınla yönetiyorsun.</p><a class="text-btn" href="${esc(state.signout)}" target="_top">Çıkış yap</a>`:`<span class="eyebrow">KEŞİFLERİN SENİ TAKİP ETSİN</span><h2>Koleksiyonun için giriş yap.</h2><p class="subtle">Oyunlarını, notlarını ve özel listelerini hesabında sakla. Başka cihazdan açtığında kaldığın yerden devam et.</p><a class="account-link" href="${esc(state.signin)}" target="_top">ChatGPT ile giriş yap </a><p class="subtle">Bu sürümde giriş ChatGPT hesabıyla sağlanır. Ayrı bir şifre oluşturmazsın.</p>`;$('accountDialog').showModal();}
function openCollection(edit=false){if(!state.user){accountDialog();return;}const l=edit?state.lists.find(x=>x.id===state.collection):null;state.editingCollection=l?.id||null;$('collectionName').value=l?.name||'';$('collectionDialogTitle').textContent=l?'Koleksiyonu düzenle':'Yeni koleksiyon';$('deleteCollection').hidden=!l;$('collectionDialog').showModal();$('collectionName').focus();}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function exportList(){download('ne-oynasam-koleksiyonum.json',{version:1,exportedAt:new Date().toISOString(),entries:[...state.entries.values()].map(e=>({...e,name:nameGame(e.gameId)?.name})),lists:state.lists.map(l=>({name:l.name,games:l.games}))});toast('Koleksiyonun dışa aktarıldı.');}
async function importEntries(data){if(!state.user){accountDialog();return;}if(data?.version!==1||!Array.isArray(data.entries)||data.entries.length>2000)throw new Error('Geçerli bir Ne Oynasam koleksiyon dosyası seç.');const resolvedIds=new Set((await hydrateGames(data.entries.map(e=>e?.gameId))).map(g=>g.id));const byId=new Map(data.entries.filter(e=>e&&resolvedIds.has(e.gameId)&&statusDefs.some(x=>x[0]&&x[0]===e.status)&&typeof e.note==='string'&&e.note.length<=1200&&(e.rating===null||Number.isInteger(e.rating)&&e.rating>=1&&e.rating<=5)).map(e=>[e.gameId,e]));const rows=[...byId.values()];if(!rows.length)throw new Error('Bu katalogla eşleşen oyun bulunamadı.');const lists=Array.isArray(data.lists)?data.lists.filter(l=>typeof l.name==='string'&&l.name.trim()&&l.name.trim().length<=60&&Array.isArray(l.games)).slice(0,30):[];let n=0;const button=$('importList');button.disabled=true;try{for(let start=0;start<rows.length;start+=40){button.textContent=`Aktarılıyor ${Math.min(start+40,rows.length)}/${rows.length}…`;const chunk=rows.slice(start,start+40).map(e=>({gameId:e.gameId,status:e.status,note:e.note,rating:e.rating}));await api('/api/library/import','POST',{entries:chunk});n+=chunk.length;}for(const l of lists){const games=[...new Set(l.games.filter(id=>byId.has(id)))];if(!games.length)await api('/api/library/import','POST',{collectionName:l.name.trim(),games:[]});else for(let start=0;start<games.length;start+=40)await api('/api/library/import','POST',{collectionName:l.name.trim(),games:games.slice(start,start+40)});}toast(`${n} oyun ve ${lists.length} koleksiyon hesabına aktarıldı.`);}catch(e){throw new Error(`${e.message} ${n} oyun aktarılmış olabilir; yeniden denemek kayıtları çoğaltmaz.`);}finally{await loadLibrary();await libraryChanged();button.disabled=false;button.textContent='İçe aktar ↓';}}
function info(type){
 const catalogInfo=`<span class="eyebrow">KEŞFİN ARKASINDA</span><h2>Bir sonraki dünyanı bul.</h2><div class="info-body"><h3>Oyun keşfi</h3><p>PC oyunlarını tür, işletim sistemi ve ruh haliyle daralt; oyuna özgü kısa tanıtımlardan sana yakın gelen dünyayı seç. Bilgisi bulunmayan alanlar “belirtilmemiş” olarak gösterilir.</p><h3>Ortak türlerden başka dünyalar</h3><p>Benzer dünyaları ve oynanış biçimlerini bir araya getiriyoruz. Her oyunun altında en fazla 20 öneri bulunur. Katalog büyüdükçe yeni oyunlar da bu eşleşmelere katılır; kullanıcı puanı öneri sırasını değiştirmez.</p><h3>Puanları okurken</h3><p>Metacritic kullanıcı puanı 0–10, olumlu mağaza yorumları ise yüzde olarak gösterilir. İki ölçü birbirinden ayrıdır. Kullanıcı puanları tarihli kayıtlardır; canlı puan değildir. Platform bilgisi bulunmayan kaynak kayıtları platform belirtilmemiş olarak gösterilir. Ölçüm tarihi bilinmeyen kayıtlar ayrıca belirtilir. Puan bulunmayan oyunlarda “Veri yok” gösterilir.</p><h3>Senin koleksiyonun</h3><p>Oyunları listene ekle, kendi puanını ver, notlarını tut ve karşılaştır. Görüntülenme sayacı bu sitede açılan oyun detaylarını aynı hesap ve oyun için günde bir kez sayar.</p><h3>Tanıtımlar ve görseller</h3><p>Keşif cümleleri, ruh halleri ve seçkiler editoryal olarak hazırlanır. Kapaklar, fragmanlar ve ekran görüntüleri ilgili yayıncılara ve diğer hak sahiplerine aittir. Bu site bağımsız bir oyun keşif hizmetidir.</p><p><a href="/lisanslar.html">Lisanslar ve katkılar</a></p></div>`;
 const privacy=`<span class="eyebrow">GİZLİLİK BİLGİSİ</span><h2>Listelerin sana ait.</h2><div class="info-body"><p>Giriş ChatGPT tarafından sağlanır; şifren saklanmaz. Hesap adı ve e-posta giriş durumunu göstermek için kullanılır. Oyunlar, durumlar, notlar, puanlar ve özel listeler Sites'a özgü kullanıcı kimliğinle eşleştirilerek veritabanında saklanır.</p><p>Notların ve koleksiyonların diğer ziyaretçilere gösterilmez. Oyunu listenden kaldırınca kişisel not ve puan da silinir. Görüntülenme tekrarlarını önlemek için hashlenmiş hesap kimliği, oyun kimliği ve gün saklanır.</p><h3>Dış bağlantılar</h3><p>Kapaklar, galeri görselleri ve seçtiğin video akışları yayıncıların görsel ve video sunucularından yüklenir. Yazı tipleri Google Fonts'tan gelir. Bu bağlantılar tarayıcının IP adresi gibi teknik bilgilerin sağlayıcılara iletilmesine neden olur. Tema ve karşılaştırma seçimleri tarayıcında tutulur.</p><h3>Altyapı</h3><p>Barındırma ChatGPT Sites tarafından sağlanır; platform teknik erişim kayıtları tutabilir. Liste dosyanı dışa aktarabilir, önceki tarayıcı listeni isteğinle hesabına taşıyabilirsin.</p><p><a href="/lisanslar.html">Lisanslar ve katkılar</a></p></div>`;
 $('infoContent').innerHTML=type==='privacy'?privacy:catalogInfo;$('infoDialog').showModal();
}
function scoreDetails(g){return `<div class="rating-panel">${scoreBadge(g,true)}</div>`;}
document.addEventListener('error',e=>{const img=e.target;if(!img?.classList?.contains('game-photo'))return;const fallback=img.dataset.fallback;if(fallback&&img.dataset.tried!=='yes'){let valid=false;try{const u=new URL(fallback);valid=u.protocol==='https:'&&u.hostname.endsWith('.steamstatic.com');}catch{}if(valid){img.dataset.tried='yes';img.src=fallback;return;}}img.outerHTML=`<div class="cover-unavailable"><span>${esc(img.dataset.gameName)}</span><small>Kapak yüklenemedi</small></div>`;},true);
async function migrateLegacy(){if(!state.user)return;const aliases={hollow:'hollow-knight',outer:'outer-wilds',stardew:'stardew-valley',disco:'disco-elysium',portal:'portal-2'};const candidates=legacy.map(id=>aliases[id]||id);const resolvedIds=new Set((await hydrateGames(candidates)).map(g=>g.id));const ids=candidates.filter(id=>resolvedIds.has(id));let n=0;for(const id of ids){if(!state.entries.has(id)){await api('/api/library','POST',{gameId:id,status:'planned',note:'',rating:null});n++;}}localStorage.removeItem('neoynasam-list');legacy=[];await loadLibrary();$('notice').hidden=true;await libraryChanged();toast(`${n} oyun eski listenden hesabına taşındı.`);}
async function refreshData(){if(!state.user){accountDialog();return;}const button=$('refreshData');const ids=state.games.filter(g=>g.steamAppId).map(g=>g.id);if(!ids.length){toast('Bu sayfada yenilenebilir oyun kaydı bulunamadı.');return;}button.disabled=true;let n=0,failed=0;try{const total=Math.ceil(ids.length/4);for(let batch=0;batch<total;batch++){button.textContent=`Mağaza bilgisi ${batch+1}/${total}…`;const r=await api('/api/catalog','POST',{ids:ids.slice(batch*4,(batch+1)*4)});const updates=new Map(r.games.map(g=>[g.id,g]));rememberGames(r.games);state.games=state.games.map(g=>updates.get(g.id)||g);state.fetchedAt=r.fetchedAt;n+=r.updated;failed+=r.failed.length;}$('sourceDate').textContent='Mağaza güncellemesi: '+new Date(state.fetchedAt).toLocaleString('tr');toast(`${n} oyun mağaza kaydı yenilendi.${failed?' '+failed+' kayıt korunarak atlandı.':''} Metacritic tarihli puan kaydı değişmedi.`);}catch(e){toast(e.message);}finally{pageCache.clear();await loadPage({force:true});if(state.current){state.current=nameGame(state.current.id)||state.current;renderRelated();}button.disabled=false;button.textContent='Bu sayfayı güncelle ';}}
async function init(){const legacyPath=legacyCollectionPath();if(legacyPath){location.replace(legacyPath);return;}try{const requestedGame=new URLSearchParams(location.search).get('game');const me=await api('/api/me');state.user=me.user;state.signin=me.signin;state.signout=me.signout;applyUrl();$('quizMoods').innerHTML=moodDefs.filter(m=>m[0]).map(([id,iconName,label],n)=>`<label><input type="radio" name="mood" value="${id}" ${n===0?'checked':''}>${icon(iconName)} ${label}</label>`).join('');if(state.user)try{await loadLibrary();}catch(e){showNotice(e.message,true);}if(!await loadPage())return;try{await hydrateGames([...state.compare]);for(const id of state.compare)if(!nameGame(id))state.compare.delete(id);}catch(e){toast('Karşılaştırma kayıtları yüklenemedi. Yeniden deneyebilirsin.');}renderCompareTray();if(pageView==='discover')initSpotlight();$('footerYear').textContent=new Date().getFullYear();if(state.user&&legacy.length){$('notice').hidden=false;$('notice').innerHTML='Önceki prototipteki oyun listen bu tarayıcıda duruyor. <button id="migrateLegacy">Hesabıma taşı</button>';}if(requestedGame)await openGame(requestedGame);if(pageView==='library'&&!state.user)showNotice('Koleksiyonunu görmek için hesabına giriş yap.');}catch(e){$('grid').innerHTML=`<div class="empty"><h3>Katalog şu an yüklenemedi.</h3><p>${esc(e.message)}</p><button id="reload">Yeniden dene</button></div>`;$('resultCount').textContent='Bağlantı bekleniyor';}}
document.addEventListener('click',async e=>{const range=e.target.closest('[data-clear-range]');if(range){for(const key of range.dataset.clearRange.split(','))$(key).value='';await submitSearch();return;}const save=e.target.closest('[data-save]');if(save){await toggle(save.dataset.save);return;}const cmp=e.target.closest('[data-compare]');if(cmp){compareToggle(cmp.dataset.compare);return;}const op=e.target.closest('[data-open]');if(op){await openGame(op.dataset.open);return;}const cop=e.target.closest('[data-compare-open]');if(cop){$('compareDialog').close();await openGame(cop.dataset.compareOpen);return;}const m=e.target.closest('[data-mood]');if(m){state.mood=m.dataset.mood;state.curation='';state.page=1;await loadPage();return;}const cur=e.target.closest('[data-curation]');if(cur){if(pageView!=='discover'){location.assign('/?mood='+encodeURIComponent(cur.dataset.curation));return;}state.mood=state.mood===cur.dataset.curation?'':cur.dataset.curation;state.curation='';state.page=1;await loadPage();$('explore').scrollIntoView({behavior:'smooth'});return;}const st=e.target.closest('[data-status]');if(st){state.status=st.dataset.status;state.page=1;await loadPage();return;}const close=e.target.closest('[data-close]');if(close){$(close.dataset.close).close();return;}const id=e.target.id;if(id==='emptyReset'){if(state.tab==='library'&&!state.entries.size)mode('discover');else clear();}if(id==='prevPage'||id==='nextPage'){state.page+=id==='nextPage'?1:-1;await loadPage();$('explore').scrollIntoView({behavior:'smooth'});}if(id==='reload')init();if(id==='retryCatalog')loadPage({force:true});const imported=e.target.closest('[data-import-qid]');if(imported){imported.disabled=true;try{const r=await api('/api/source','POST',{qid:imported.dataset.importQid});const game=r.game;rememberGames([game]);pageCache.clear();await clear();detail(game);toast('Oyun kataloğa eklendi.');}catch(err){toast(err.message);imported.disabled=false;}return;}if(id==='accountLibrary'){$('accountDialog').close();mode('library');}if(id==='migrateLegacy')try{await migrateLegacy();}catch(err){toast(err.message);}if(id==='shareGame'){try{await navigator.clipboard.writeText(location.href);toast('Oyun bağlantısı kopyalandı.');}catch{toast('Adres çubuğundaki bağlantıyı kopyalayabilirsin.');}}if(id==='assignAdd'||id==='assignRemove'){try{await api('/api/lists','POST',{action:id==='assignAdd'?'add':'remove',listId:$('assignCollection').value,gameId:state.current.id});await loadLibrary();await libraryChanged();detail(state.current,false);toast(id==='assignAdd'?'Koleksiyona eklendi.':'Koleksiyondan çıkarıldı.');}catch(err){toast(err.message);}}});
document.addEventListener('change',async e=>{if(e.target.id==='pageJump'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>0&&n<=state.pageCount){state.page=n;await loadPage();$('explore').scrollIntoView({behavior:'smooth'});}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='entryForm')return;e.preventDefault();const id=state.current.id;const data={status:$('entryStatus').value,note:$('entryNote').value,rating:$('entryRating').value?Number($('entryRating').value):null};if(await saveGame(id,data)){toast('Durum, puan ve not kaydedildi.');if(state.current?.id===id)detail(state.current,false);}});
for(const id of ['genre','era','sort','system','features'])$(id).addEventListener('change',()=>{state.page=1;return loadPage();});$('search').addEventListener('input',()=>{catalogSequence++;catalogController?.abort();clearTimeout(searchTimer);searchTimer=setTimeout(submitSearch,300);});$('search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();submitSearch();}});$('search').addEventListener('search',submitSearch);if($('searchSubmit'))$('searchSubmit').onclick=submitSearch;$('reset').onclick=clear;$('resetScoreFilters').onclick=()=>{clearRanges();return submitSearch();};if($('clearCuration'))$('clearCuration').onclick=()=>{state.mood='';state.curation='';state.page=1;return loadPage();};if($('surprise'))$('surprise').onclick=async()=>{const button=$('surprise');button.disabled=true;try{if(!checkRanges())return;const r=await api('/api/catalog?'+catalogQuery({random:true}));if(!r.games?.length){toast('Önce filtrelerini genişlet.');return;}rememberGames(r.games);detail(r.games[0]);}catch(e){toast(e.message);}finally{button.disabled=false;}};$('close').onclick=()=>$('detail').close();$('detail').addEventListener('close',()=>{detailSequence++;closeMedia();state.current=null;scheduleSpotlight();syncUrl();render();});for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});$('themeToggle').onclick=()=>{document.body.classList.toggle('dark');$('themeToggle').innerHTML=icon(document.body.classList.contains('dark')?'sun':'moon');$('themeToggle').setAttribute('aria-label',document.body.classList.contains('dark')?'Açık temaya geç':'Karanlık temaya geç');try{localStorage.setItem('neoynasam-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}};$('account').onclick=accountDialog;$('compareNow').onclick=showCompare;$('compareClear').onclick=()=>{state.compare.clear();render();};if($('startQuiz'))$('startQuiz').onclick=()=>$('quiz').showModal();$('quizForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target);if(pageView!=='discover'){const q=new URLSearchParams({mood:form.get('mood')||'',system:form.get('system')||'',era:form.get('era')||''});location.assign('/?'+q);return;}state.mood=form.get('mood');state.curation='';state.status='';state.page=1;clearRanges();for(const id of ['search','genre','features'])$(id).value='';$('sort').value='editor';$('system').value=form.get('system')||'';$('era').value=form.get('era');$('quiz').close();await loadPage();showNotice('Sonuçlar ruh hali, PC işletim sistemi ve dönem tercihlerine göre filtrelendi. Ruh hali sınıflandırması editoryaldir.');};$('collectionSelect').onchange=()=>{state.collection=$('collectionSelect').value;state.page=1;return loadPage();};$('newCollection').onclick=()=>openCollection();$('manageCollection').onclick=()=>openCollection(true);$('collectionForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{await api('/api/lists','POST',{action:state.editingCollection?'rename':'create',listId:state.editingCollection,name:$('collectionName').value});await loadLibrary();$('collectionDialog').close();await libraryChanged();toast('Koleksiyon kaydedildi.');}catch(err){toast(err.message);}finally{button.disabled=false;}};$('deleteCollection').onclick=async()=>{if(!confirm('Bu koleksiyon silinsin mi? Oyunların ana listende kalacak.'))return;try{await api('/api/lists','POST',{action:'delete',listId:state.editingCollection});state.collection='';await loadLibrary();$('collectionDialog').close();await libraryChanged();toast('Koleksiyon silindi.');}catch(e){toast(e.message);}};$('exportList').onclick=exportList;$('importList').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>4000000)throw new Error('Dosya en fazla 4 MB olabilir.');const data=JSON.parse(await f.text());if(!confirm('Dosyadaki oyunlar hesabına aktarılacak. Eşleşen oyunların not ve durumları dosyadaki değerlerle güncellenecek. Devam edilsin mi?'))return;await importEntries(data);}catch(err){toast(err.message);}finally{e.target.value='';}};$('refreshData').onclick=refreshData;if($('about'))$('about').onclick=()=>info('sources');$('sources').onclick=()=>info('sources');$('privacy').onclick=()=>info('privacy');for(const r of scoreRanges)for(const key of [r.min,r.max]){$(key).addEventListener('input',()=>{catalogSequence++;catalogController?.abort();clearTimeout(searchTimer);checkRanges();searchTimer=setTimeout(submitSearch,350);});$(key).addEventListener('change',submitSearch);$(key).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();submitSearch();}});}$('mcFilterBrand').innerHTML=scoreBrand('metacritic');$('steamFilterBrand').innerHTML=scoreBrand('steam');hydrateIcons();$('themeToggle').innerHTML=icon(document.body.classList.contains('dark')?'sun':'moon');init();

$('searchSource').onclick=async()=>{if(!state.user){accountDialog();return;}const q=$('search').value.trim();if(q.length<3){toast('Arama alanına en az üç karakterlik bir oyun adı yaz.');$('search').focus();return;}const button=$('searchSource');button.disabled=true;$('sourceResults').innerHTML='<p class=\"subtle\">Yeni oyunlar aranıyor…</p>';try{const r=await api('/api/source?q='+encodeURIComponent(q));$('sourceResults').innerHTML=r.games.length?'<div class=\"source-found\">'+r.games.map(g=>'<div><strong>'+esc(g.name)+'</strong><span>'+esc(g.year||'Yıl belirtilmemiş')+' · '+esc(g.genres.join(', ')||'Tür belirtilmemiş')+'</span><button data-import-qid=\"'+esc(g.qid)+'\">Kataloğa ekle </button></div>').join('')+'</div>':'<p class=\"subtle\">Kaynakta doğrulanmış video oyunu kaydı bulunamadı.</p>';}catch(e){$('sourceResults').textContent=e.message;}finally{button.disabled=false;}};
